package org.millenaire.common.utilities;
public class Point { public final double x,y,z; public Point(double x,double y,double z){this.x=x;this.y=y;this.z=z;} public void write(net.minecraft.nbt.CompoundTag tag,String key){tag.putDouble(key+"_xCoord",x);tag.putDouble(key+"_yCoord",y);tag.putDouble(key+"_zCoord",z);} public static Point read(net.minecraft.nbt.CompoundTag tag,String key){return tag.contains(key+"_xCoord")?new Point(tag.getDouble(key+"_xCoord"),tag.getDouble(key+"_yCoord"),tag.getDouble(key+"_zCoord")):null;} public int getChunkX(){return ((int)x)>>4;} public int getChunkZ(){return ((int)z)>>4;} }